CREATE TABLE IF NOT EXISTS identity_storage_charges (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES identity_organizations(id), identity_id TEXT NOT NULL REFERENCES identity_subjects(id), resource_id TEXT NOT NULL REFERENCES identity_resources(id), intent_key TEXT NOT NULL, bytes BIGINT NOT NULL CHECK(bytes >= 0), provenance_sha256 TEXT NOT NULL, request_sha256 TEXT NOT NULL, created_at BIGINT NOT NULL, receipt TEXT NOT NULL, UNIQUE(organization_id,identity_id,intent_key));
